<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role(['Faculty']);
$user=current_user();$faculty=$pdo->prepare('SELECT f.*,d.name department_name FROM faculty f JOIN departments d ON d.id=f.department_id WHERE f.user_id=?');$faculty->execute([$user['id']]);$faculty=$faculty->fetch();
$pending=$pdo->prepare('SELECT COUNT(*) FROM department_clearances WHERE department_id=? AND status=\'Pending\'');$pending->execute([$faculty['department_id']]);$pending=$pending->fetchColumn();
$approved=$pdo->prepare('SELECT COUNT(*) FROM approvals WHERE approver_user_id=? AND status=\'Approved\'');$approved->execute([$user['id']]);$approved=$approved->fetchColumn();
$students=$pdo->prepare('SELECT COUNT(*) FROM students WHERE department_id=?');$students->execute([$faculty['department_id']]);$students=$students->fetchColumn();
$pageTitle='Faculty Dashboard | CLEARX';require_once __DIR__.'/../includes/header.php';
